import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {Game} from '../src/game/sim.ts';
import {encodeGame,decodeGame,validateGameSave} from '../src/game/persistence.ts';
const SEED=1454491798,REQUEST={preset:'river-valley',size:1040};
// Captured from the actual published714b47e built V20 world, not a hash
// regenerated by the implementation under test.
const PUBLISHED_V20='7467c9768d2e1db2170d45a2324d6e80f55961d6e02468487756974be3305dc6';
// Incoming77f9d90 shared-generator output, before the compatibility split.
// That path ignored generation>=20, so it is the current V21 terrain reference.
const INCOMING_V21='752327eb0f367ab87a80f83815b11219cfc0a4b54b0532762eb3fe611ecbcada';
const heightHash=g=>{const h=g.world.heights;return createHash('sha256').update(Buffer.from(h.buffer,h.byteOffset,h.byteLength)).digest('hex');};
const bodies=g=>g.state.units.map(u=>({id:u.id,team:u.team,type:u.type,x:u.x,y:u.y,z:u.z,hp:u.hp,carry:u.carry,carryType:u.carryType,carryFood:u.carryFood??null,itemCargo:u.itemCargo??{},farmTool:u.farmTool??null,basket:u.basket??null,waterVessel:u.waterVessel??null,garment:u.garment??null}));
for(const [version,expected] of [[20,PUBLISHED_V20],[21,INCOMING_V21]]){
 test(`native generation${version} preserves its own exact terrain and physical bodies across strict save reload`,()=>{
  const g=new Game();g.reset(SEED,version,REQUEST);g.enterIsland();assert.equal(g.state.worldgenVersion,version);assert.equal(g.world.options.preset,'river-valley');assert.equal(g.world.size,1040);assert.equal(heightHash(g),expected);
  // Ordinary native steps only; no edited heights/resources or authored actors.
  g.state.paused=false;for(let i=0;i<4;i++)g.step(.25);g.state.paused=true;assert.deepEqual(g.simulationErrors,[]);assert.equal(heightHash(g),expected);
  const before=bodies(g),ids=g.state.units.map(u=>u.id),camp=JSON.stringify(g.world.camps),raw=JSON.parse(JSON.stringify(encodeGame(g)));validateGameSave(raw);const restored=decodeGame(raw);
  assert.equal(restored.state.worldgenVersion,version);assert.equal(heightHash(restored),expected);assert.equal(JSON.stringify(restored.world.camps),camp);assert.deepEqual(restored.state.units.map(u=>u.id),ids);assert.deepEqual(bodies(restored),before);assert.equal(restored.state.nextId,g.state.nextId);assert.deepEqual(restored.state.tribes,g.state.tribes);assert.equal(restored.world.options.preset,'river-valley');
  if(version===21){assert.notEqual(heightHash(restored),PUBLISHED_V20,'fresh V21 must retain current generator rather than silently reuse V20');const bad=structuredClone(raw);bad.state.worldgenVersion=22;assert.throws(()=>validateGameSave(bad),'unqualified future versions stay rejected');}
 });
}
